package com.example.battleshipgame.views;
import android.content.*;import android.os.Bundle;import android.view.Gravity;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.battleshipgame.customview.BattleshipBoardView;import com.example.battleshipgame.logic.Board;import com.example.battleshipgame.ui.Ui;
public class SetupActivity extends AppCompatActivity {private final Board board=new Board();private BattleshipBoardView view;@Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout page=Ui.page(this);page.setGravity(Gravity.CENTER_HORIZONTAL);TextView eyebrow=Ui.text(this,"FLEET DEPLOYMENT",11,Ui.CYAN);eyebrow.setLetterSpacing(.16f);Ui.spaced(page,eyebrow,2);TextView title=Ui.text(this,"הצב את הצי",28,Ui.INK);title.setTypeface(null,1);Ui.spaced(page,title,4);Ui.spaced(page,Ui.text(this,"בחר פריסה אוטומטית, ואז צא לקרב.",15,Ui.MUTED),3);view=new BattleshipBoardView(this);view.setBoard(board,true);LinearLayout.LayoutParams boardLp=new LinearLayout.LayoutParams(-1,0,1);boardLp.topMargin=Ui.dp(this,18);page.addView(view,boardLp);TextView hint=Ui.text(this,"הספינות שלך מוצגות בכחול בהיר",13,Ui.MUTED);Ui.spaced(page,hint,8);Button random=Ui.button(this,"⟳  פריסה אוטומטית",false);random.setOnClickListener(v->{board.placeRandomFleet();view.invalidate();});Ui.spaced(page,random,12);Button start=Ui.button(this,"התחל קרב  ◀",true);start.setOnClickListener(v->{if(board.getShips().isEmpty()){Toast.makeText(this,"קודם יש לפרוס את הצי",Toast.LENGTH_SHORT).show();return;}Intent i=new Intent(this,GameActivity.class);i.putExtra("board",board);startActivity(i);});Ui.spaced(page,start,10);setContentView(page);}}
